"""Isolated numerical-policy candidates; these are not upstream library bug fixes.
Weights, boundary dtypes, labels, model structure and adapter initial state stay
unchanged. Promote only the named contraction, then round to the original dtype.
"""
import torch,types

def install(model,accelerated,mode):
 if mode=='qkv-attention-fp32':
  q=install(model,accelerated,'qkv-fp32');att=install(model,accelerated,'attention-fp32')
  return dict(classification='numerical-policy adjustment',mode=mode,components=[q,att])
 record=dict(classification='numerical-policy adjustment',mode=mode,calls=[])
 if mode=='qkv-fp32':
  names=[]
  for name,module in model.named_modules():
   if name.endswith('.linear_attn.in_proj_qkv'):
    assert isinstance(module,torch.nn.Linear) and not module.weight.requires_grad
    names.append(name)
    def forward(self,x,_name=name):
     y=torch.nn.functional.linear(x.float(),self.weight.float(),None if self.bias is None else self.bias.float()).to(x.dtype)
     record['calls'].append(dict(module=_name,weight_dtype=str(self.weight.dtype),input_dtype=str(x.dtype),output_dtype=str(y.dtype),shape=list(y.shape)))
     return y
    module.forward=types.MethodType(forward,module)
  assert len(names)==24,names
  record['scope']=names
 elif mode=='oproj7-backward-fp32':
  name='base_model.model.model.language_model.layers.7.self_attn.o_proj'
  module=dict(model.named_modules())[name]
  assert isinstance(module,torch.nn.Linear) and not module.weight.requires_grad and module.bias is None
  class FrozenBackwardPolicy(torch.autograd.Function):
   @staticmethod
   def forward(ctx,x,w):
    ctx.save_for_backward(w);ctx.input_dtype=x.dtype
    return torch.nn.functional.linear(x,w)
   @staticmethod
   def backward(ctx,dy):
    (w,)=ctx.saved_tensors
    return (dy.float()@w.float()).to(ctx.input_dtype),None
  def forward(self,x):
   y=FrozenBackwardPolicy.apply(x,self.weight)
   record['calls'].append(dict(module=name,forward='unchanged native BF16 F.linear',backward='FP32 dy @ W, rounded BF16',shape=list(y.shape)))
   return y
  module.forward=types.MethodType(forward,module)
  record['scope']=[name];record['attention_backend']='unchanged native fused attention'
 elif mode=='attention-fp32':
  def kernel(q,k,v,scale,side):
   score=q.float()@k.float().transpose(-1,-2)*scale
   mask=torch.ones(score.shape[-2:],device=q.device,dtype=torch.bool).triu(1)
   y=(score.masked_fill(mask,float('-inf')).softmax(-1)@v.float()).to(q.dtype)
   record['calls'].append(dict(module='full_attention',device=str(q.device),shape=list(q.shape),input_dtype=str(q.dtype),output_dtype=str(y.dtype),kernel='FP32 QK/softmax/AV, BF16 boundary'))
   return y
  accelerated.kernel=kernel;record['scope']='8 full-attention contractions; unchanged BF16 Q/K/V and outputs'
 else:raise ValueError(mode)
 return record

