"""Compare complete adapter gradients from a labeled causal intervention, not a repair."""
import json,sys,re
from pathlib import Path
import numpy as np
R=Path(__file__).resolve().parent
sys.path.insert(0,str(R.parents[3]/'skills/precision-compare/scripts'))
from array_compare import compare_arrays

def read(path):return json.loads(path.read_text())
def main(boundary):
 mode='cotangent-boundary'+str(boundary)
 dirs={s:R/(s+'-'+mode+'-evidence/artifacts') for s in ['gpu','npu']}
 diagnostics={s:read(p/'intervention.json' if (p/'intervention.json').exists() else R/(s+'-'+mode+'-analysis-evidence/artifacts/intervention.json')) for s,p in dirs.items()}
 configs={s:read(p/'configuration.json') for s,p in dirs.items()}
 for field in ['ids','mask','positions','labels','trainable']:assert configs['gpu'][field]==configs['npu'][field],field
 assert all(c['initial_exact'] for c in configs.values())
 arrays={}
 for s,p in dirs.items():
  with np.load(p/'gradients.npz') as z:arrays[s]={n:z[n] for n in z.files}
 expected=list(configs['gpu']['trainable']);assert set(expected)==set(arrays['gpu'])==set(arrays['npu'])
 groups={}
 for label,predicate in [('lower',lambda i:i<boundary),('upper',lambda i:i>=boundary),('layer7',lambda i:i==7)]:
  names=[n for n in expected if predicate(int(re.search(r'\.layers\.(\d+)\.',n).group(1)))]
  groups[label]=compare_arrays({n:arrays['gpu'][n] for n in names},{n:arrays['npu'][n] for n in names},expected=names,metrics=True)
 coord='base_model.model.model.language_model.layers.7.self_attn.v_proj.lora_B.default.weight'
 target={s:float(arrays[s][coord][302,1]) for s in arrays}
 original=read(R/'boundaries-comparison.json')['target_coordinate'];original_gap=original['npu']['gradient']-original['gpu']['gradient']
 newgap=target['npu']-target['gpu']
 n=diagnostics['npu'];ratio=n['layer7_gout_vs_gpu_baseline']['metrics']['error_norm']['value']/n['own_baseline_layer7_gout_vs_gpu_baseline']['metrics']['error_norm']['value']
 report=dict(classification='common-cotangent causal diagnostic; not original-loss gradient or accepted repair',boundary=boundary,target_gradient=target,original_target_gradient=original,original_target_gap=original_gap,diagnostic_target_gap=newgap,target_gap_ratio=newgap/original_gap,layer7_gout_error_norm_ratio=ratio,diagnostics=diagnostics,gradient_groups=groups)
 p=R/(mode+'-comparison.json');assert not p.exists();p.write_text(json.dumps(report,indent=2)+'\n')
 print(json.dumps({k:report[k] for k in ['boundary','target_gradient','original_target_gap','diagnostic_target_gap','target_gap_ratio','layer7_gout_error_norm_ratio']},indent=2))
 for name,g in groups.items():print(name,'cosine',g['metrics']['cosine']['value'],'error_l2',g['metrics']['error_norm']['value'])
if __name__=='__main__':main(int(sys.argv[1]))
